const counts = {};

items.forEach(item => {
  if (item.json.dataType === 'caselogged') {
    const { date, agent, source } = item.json;
    if (source !== 'E-mail') return;
    const key = `${date}__${agent}`;
    if (!counts[key]) {
      counts[key] = { date, agent, CaseLogged: 0, CaseLoggedCall: 0, Resolved: 0, Reassigned: 0, EmailTags: 0 };
    }
    counts[key].CaseLogged += item.json.CaseLogged || 0;
    return;
  }

  if (item.json.dataType === 'caseloggedcall') {
    const { date, agent } = item.json;
    const key = `${date}__${agent}`;
    if (!counts[key]) {
      counts[key] = { date, agent, CaseLogged: 0, CaseLoggedCall: 0, Resolved: 0, Reassigned: 0, EmailTags: 0 };
    }
    counts[key].CaseLoggedCall += item.json.CaseLoggedCall || 0;
    return;
  }

  if (item.json.dataType === 'casesclosed') {
    const { date, agent } = item.json;
    const key = `${date}__${agent}`;
    if (!counts[key]) {
      counts[key] = { date, agent, CaseLogged: 0, CaseLoggedCall: 0, Resolved: 0, Reassigned: 0, EmailTags: 0 };
    }
    counts[key].Resolved += item.json.CasesClosed || 0;
    return;
  }

  if (item.json.dataType === 'reassigned') {
    const { date, agent } = item.json;
    const key = `${date}__${agent}`;
    if (!counts[key]) {
      counts[key] = { date, agent, CaseLogged: 0, CaseLoggedCall: 0, Resolved: 0, Reassigned: 0, EmailTags: 0 };
    }
    counts[key].Reassigned += item.json.Reassigned || 0;
    return;
  }

  if (item.json.sourceFolder === 'Sent') {
    const categories = item.json.categories || [];
    const rawDate = item.json.sentDateTime;
    const date = rawDate ? rawDate.slice(0, 10) : null;
    if (!date) return;

    const NON_AGENT_CATEGORIES = [
      'case logged','urgent','follow up','resolved','pending',
      'inbox','sent','important mail','important','high priority',
      'low priority','escalated','on hold','closed',
      'case closed','cases closed','case update','house keeping',
      'housekeeping','fm','non relevant','auto response','vmm','it','store',
      'ho','engineer','rm','unassigned'
    ];

    let agent = 'Unassigned';
    for (const cat of categories) {
      const catLower = cat.toLowerCase().trim();
      if (/^\d+$/.test(catLower)) continue;
      if (catLower && !NON_AGENT_CATEGORIES.includes(catLower)) {
        agent = cat;
        break;
      }
    }

    const NAME_MAP = {
      'Prince Kumar Singh': 'Prince',
      'Sachin Yadav': 'Sachin'
    };
    if (NAME_MAP[agent]) agent = NAME_MAP[agent];

    const key = `${date}__${agent}`;
    if (!counts[key]) {
      counts[key] = { date, agent, CaseLogged: 0, CaseLoggedCall: 0, Resolved: 0, Reassigned: 0, EmailTags: 0 };
    }

    const isCaseLogged = categories.some(c => c.toLowerCase().includes('case logged'));
    if (isCaseLogged) counts[key].EmailTags += 1;
    return;
  }
});

return Object.values(counts)
  .filter(row => row.date && row.agent)
  .sort((a, b) => (a.date || '').localeCompare(b.date || '') || (a.agent || '').localeCompare(b.agent || ''))
  .map(row => ({ json: row }));

const now = new Date();
const currentDay = now.getDate();

let startDate, endDate, reportType;

if (currentDay === 1) {
  const prevMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  startDate = new Date(prevMonth.getFullYear(), prevMonth.getMonth(), 1);
  endDate = new Date(prevMonth.getFullYear(), prevMonth.getMonth() + 1, 0, 23, 59, 59);
  reportType = "Previous Full Month";
} else {
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  startDate = new Date(now.getFullYear(), now.getMonth(), 1);
  endDate = new Date(yesterday.getFullYear(), yesterday.getMonth(), yesterday.getDate(), 23, 59, 59);
  reportType = "MTD";
}

return [{
  json: {
    startDate: startDate.toISOString(),
    endDate: endDate.toISOString(),
    reportType,
    startDateFormatted: startDate.toLocaleDateString('en-GB'),
    endDateFormatted: endDate.toLocaleDateString('en-GB')
  }
}];

return items.map(item => {
  return {
    json: {
      date: item.json.date,
      agent: item.json.agent,
      source: item.json.sourcesofcomplaint || 'Unknown',
      CaseLogged: item.json.CaseLogged,
      dataType: 'caselogged'
    }
  };
});

return items.map(item => {
  return {
    json: {
      date: item.json.date,
      agent: item.json.agent,
      CasesClosed: item.json.CasesClosed,
      dataType: 'casesclosed'
    }
  };
});

const NAME_MAP = {
  'Prince': 'Prince Kumar Singh',
  'Sachin': 'Sachin Yadav'
};

return items.map(item => {
  let agent = item.json.agent;
  if (NAME_MAP[agent]) agent = NAME_MAP[agent];
  return {
    json: {
      date: item.json.date,
      agent,
      Reassigned: item.json.Reassigned,
      dataType: 'reassigned'
    }
  };
});

const NAME_MAP = {
  'Prince Kumar Singh': 'Prince',
  'Sachin Yadav': 'Sachin'
};

const CASE_MAP = {
  'yakoob': 'Yakoob'
};

return items.map(item => {
  let agent = item.json.agent || item.json.name || '';

  if (NAME_MAP[agent]) agent = NAME_MAP[agent];

  if (agent) {
    const agentLower = agent.toLowerCase();
    if (CASE_MAP[agentLower]) agent = CASE_MAP[agentLower];
  }

  return {
    json: {
      ...item.json,
      agent
    }
  };
});

// Mirrors Code37 (caseloggedcall) + Code34-filtered-to-email (caselogged) shapes,
// so this new source merges into the same Count emails9 buckets as the old
// CRM's data -- same (date, agent) key gets summed across both systems
// (team is working in both CRMs concurrently, no cutover date).
// Agent names normalized to the same short form the old pipeline converges
// to ('Yakoob', 'Sachin') via Code in JavaScript4, or this source's rows
// would land in a separate, un-merged bucket.
const NAME_MAP = { 'Yakoob Khan': 'Yakoob', 'Sachin Yadav': 'Sachin' };
const out = [];
for (const item of items) {
  const j = item.json;
  const agent = NAME_MAP[j.agent] || j.agent;
  if (j.source === 'Phone') {
    out.push({ json: { date: j.date, agent, CaseLoggedCall: j.cnt, dataType: 'caseloggedcall' } });
  } else if (j.source === 'Email') {
    out.push({ json: { date: j.date, agent, source: 'E-mail', CaseLogged: j.cnt, dataType: 'caselogged' } });
  }
}
return out;

return items.map(item => {
  return {
    json: {
      date: item.json.date,
      agent: item.json.agent,
      CaseLoggedCall: item.json.CaseLoggedCall,
      dataType: 'caseloggedcall'
    }
  };
});

return items.map(item => {
  const j = item.json;
  return { json: {
    service_id: 338,
    report_date: j.date,
    agent_name: j.agent,
    resolved_cases: j.Resolved || 0,
    case_logged_email: j.CaseLogged || 0,
    case_logged_call: j.CaseLoggedCall || 0,
    reassigned: j.Reassigned || 0,
    email_tags: j.EmailTags || 0
  }};
});

function sqlVal(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  return "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}
if (items.length === 0) return [];
const cols = ['service_id','report_date','agent_name','resolved_cases','case_logged_email','case_logged_call','reassigned','email_tags'];
const rows = items.map(item => '(' + cols.map(c => sqlVal(item.json[c])).join(',') + ')');
const updateCols = cols.filter(c => !['service_id','agent_name','report_date'].includes(c));
const updateClause = updateCols.map(c => `${c}=VALUES(${c})`).join(', ');
const query = `INSERT INTO calls.crm_daily_summary (${cols.join(',')}) VALUES ${rows.join(',')} ON DUPLICATE KEY UPDATE ${updateClause};`;
return [{ json: { query, rowCount: rows.length } }];
